import json
import os
import re
import subprocess
import tempfile
import time

import requests

CONF_PATH = "/etc/who_proxy/bot.conf"
MANAGER = "/usr/local/bin/manager.sh"
CLIENTS_DIR = "/etc/who_proxy/clients"

NAME_RE = re.compile(r"^[A-Za-z0-9_-]{1,32}$")


def load_conf():
    conf = {}
    with open(CONF_PATH, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#") or "=" not in line:
                continue
            k, v = line.split("=", 1)
            conf[k.strip()] = v.strip()
    if "BOT_TOKEN" not in conf or "ADMIN_ID" not in conf:
        raise SystemExit("bot.conf missing BOT_TOKEN or ADMIN_ID")
    return conf


class TgBot:
    def init(self, token):
        self.base = "https://api.telegram.org/bot" + token

    def call(self, method, files=None, **params):
        if files:
            r = requests.post(self.base + "/" + method, data=params, files=files, timeout=70)
        else:
            r = requests.post(self.base + "/" + method, data=params, timeout=70)
        try:
            return r.json()
        except Exception:
            return {"ok": False}

    def get_updates(self, offset):
        return self.call("getUpdates", offset=offset, timeout=60)

